// LVALUE-TO-RVALUE CONVERSION (LVR)

// 1. Source: Lvalue refers to object in memory
volatile const int memory_lvalue = 10;

// Type of memory_lvalue: volatile const int

// 2. Context requiring prvalue (e.g., arithmetic)
// LVR occurs before '*' operation
auto result_int = memory_lvalue * 2;

// 3. Result of LVR: temporary prvalue (value read)
// Volatile/const qualifiers stripped during conversion

// Type of result_int: int (not volatile const int)

// LVR is standard for non-class types used as operands.
